// Fixed low165888/W16/H4/4096 observer. Artifact-only; partial profiles never estimate period.
package main
import("encoding/json";"flag";"fmt";"math";"os";"path/filepath")
type low_job struct{profile,column,input,output string;start,pre_end,stride,native_increment,increment,window,hop int;sample_rate float64;check_only bool;values []float64;raw []byte}
type low_partial_result struct{State string `json:"state"`;Early *modulation_span `json:"early"`;Late *modulation_span `json:"late"`;Delta *float64 `json:"late_minus_early_attenuation_db"`;Ratio *float64 `json:"late_over_early_median_amplitude_ratio"`;EarlyBounds [2]int `json:"early_center_bounds"`;LateBounds [2]int `json:"late_center_bounds"`;Limits []string `json:"limits"`}
func main(){var j low_job;flag.StringVar(&j.profile,"profile","","L0|L1|L2|L3");flag.StringVar(&j.column,"column","linear","public CSV signal column");flag.StringVar(&j.output,"output","","fresh report/curve directory");flag.IntVar(&j.start,"start-sample",-1,"actual host-upper+128 recorded bound");flag.IntVar(&j.pre_end,"pre-end-sample",0,"explicit independently guaranteed held bound; exactly128");flag.IntVar(&j.stride,"native-stride",1024,"fixed native stride");flag.IntVar(&j.native_increment,"native-increment",162,"source-provenance native carrier increment");flag.IntVar(&j.increment,"increment",165888,"fixed retained carrier increment; no folding");flag.IntVar(&j.window,"window",16,"fixed projection support");flag.IntVar(&j.hop,"hop",4,"fixed projection hop");flag.Float64Var(&j.sample_rate,"sample-rate",55937.5/1024,"caller recorded Fs; Hz is nominal/calibrated caller provenance");flag.BoolVar(&j.check_only,"check-only",false,"validate input/geometry only; no projection or numeric estimator");flag.Parse();if flag.NArg()!=1{fmt.Fprintln(os.Stderr,"use -profile L0|L1|L2|L3 -start-sample N -pre-end-sample 128 -output NEW_DIRECTORY [options] INPUT.csv");os.Exit(2)};j.input=flag.Arg(0);if e:=j.run();e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
func(j *low_job)run()error{
 if e:=j.prepare();e!=nil{return e};if j.check_only{return json.NewEncoder(os.Stdout).Encode(map[string]interface{}{"state":"structural_input_geometry_only_no_numeric_run","profile":j.profile,"input_sha256":public_digest(j.raw),"samples":len(j.values),"actual_horizon":len(j.values)-j.start,"minimum_horizon":j.minimum(),"horizon_eligible":len(j.values)-j.start>=j.minimum()})}
 job:=modulation_job{mode:"am",column:j.column,waveform:"periodic",increment:float64(j.increment),sample_rate:j.sample_rate,native_stride:j.stride,amplitude:8170,offset:-8,window:j.window,hop:j.hop,start:j.start,end:len(j.values),pre_end:j.pre_end,values:j.values};var e error
 if j.profile=="L0"{job.expected_period=1024;e=job.analyze()}else{e=job.analyze_partial()};if e!=nil{return e}
 reasons:=[]string{};if len(j.values)-j.start<j.minimum(){reasons=append(reasons,"insufficient_actual_horizon")};peak:=0.;for _,x:=range j.values{peak=math.Max(peak,math.Abs(x))};if peak>=32767{reasons=append(reasons,"raw_clipped")};if job.result.Gate==nil||!job.result.Gate.Stable{reasons=append(reasons,"resetheld_unqualified")};if job.result.State=="unqualified_reset_held_carrier"||job.result.State=="quantization_limited"||job.result.State=="no_signal"{reasons=append(reasons,job.result.State)}
 report:=map[string]interface{}{"state":"finite_output_observations_retained","profile":j.profile,"input":j.input,"input_sha256":public_digest(j.raw),"column":j.column,"published_modulation":job.result,"period":job.result.Period,"period_policy":"not_scored_partial_or_control","applicability_reasons":reasons,"applicable":len(reasons)==0,"raw_peak":peak,"limits":[]string{"No new physical tolerance or model-agreement gate","8170 defines log origin, not inferred full-level calibration","Raw curve unaligned; no hidden update count or partial-period extrapolation"}}
 if j.profile=="L0"{report["period_policy"]="coarse_only_original_fine_guard_retained";report["fine"]=fast_fine(&job,1024)}else{report["partial_features"]=low_partial_features(&job);if job.result.Period!=nil{return fmt.Errorf("partial period dispatch forbidden")}}
 if j.profile=="L2"{carrier,e:=fast_carrier(j.values,j.start);if e!=nil{return e};report["independent_carrier"]=carrier}
 e=os.Mkdir(j.output,0755);if e!=nil{return e};job.output=filepath.Join(j.output,"curve.csv");e=job.write_curve();if e!=nil{return e};curve,e:=os.ReadFile(job.output);if e!=nil{return e};report["curve"]=map[string]string{"path":job.output,"sha256":public_digest(curve)};raw,e:=json.MarshalIndent(report,"","  ");if e!=nil{return e};e=write_exclusive(filepath.Join(j.output,"report.json"),append(raw,'\n'));if e!=nil{return e};fmt.Println(string(raw));return nil
}
func(j *low_job)prepare()error{
 if j.profile!="L0"&&j.profile!="L1"&&j.profile!="L2"&&j.profile!="L3"{return fmt.Errorf("exact L0..L3 profile required")};if j.stride!=1024||j.native_increment!=162||j.increment!=165888||j.native_increment*j.stride!=j.increment||j.window!=16||j.hop!=4||j.pre_end!=128||j.start<j.pre_end||j.start>4096-64||!mod_finite(j.sample_rate)||j.sample_rate<=0{return fmt.Errorf("fixed geometry/provenance or bounded ROI invalid")};if e:=fresh_output(j.output);e!=nil{return e};var e error;j.input,e=absolute_path(j.input);if e!=nil{return e};j.output,e=absolute_path(j.output);if e!=nil{return e};j.raw,e=os.ReadFile(j.input);if e!=nil{return e};j.values,e=strict_public_csv(j.raw,j.column,4096);return e
}
func(j *low_job)minimum()int{if j.profile=="L0"{return 3112};return 1536}
func low_partial_features(job *modulation_job)low_partial_result{
 r:=low_partial_result{State:"unresolved_partial_support",EarlyBounds:[2]int{job.start+8,job.start+520},LateBounds:[2]int{job.end-520,job.end-8},Limits:[]string{"Continuous two-window features only; no causal assertion or period call","Actual AME0/TEST-held controls required for attribution; no new passband"}};if job.end-job.start<1536{return r};early,late:=[]modulation_point{},[]modulation_point{};a,b:=[]float64{},[]float64{};for _,p:=range job.points{if !p.valid{continue};if p.sample>=float64(r.EarlyBounds[0])&&p.sample<float64(r.EarlyBounds[1]){early=append(early,p);a=append(a,p.amplitude)};if p.sample>=float64(r.LateBounds[0])&&p.sample<float64(r.LateBounds[1]){late=append(late,p);b=append(b,p.amplitude)}};if len(early)==0||len(late)==0{return r};x,y:=mod_span(early),mod_span(late);r.Early=&x;r.Late=&y;delta:=y.Median-x.Median;r.Delta=&delta;base:=mod_quantile(a,.5);if base>=32{ratio:=mod_quantile(b,.5)/base;r.Ratio=&ratio};r.State="continuous_partial_features_no_period";return r
}
